<script setup>
import { computed } from 'vue'
const props=defineProps({metrics:{type:Object,required:true}})
const integer=(value)=>new Intl.NumberFormat('en-NG').format(Number(value||0))
const money=(minor)=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(Number(minor||0)/100)
const progress=computed(()=>Math.max(0,Math.min(100,Number(props.metrics.tickets_sold_percent||0))))
</script>
<template><div class="stat-strip" aria-label="Event performance metrics"><article class="stat-cell stat-cell--tickets"><div class="stat-cell-label">Tickets sold</div><div class="stat-cell-value">{{ integer(metrics.tickets_sold) }}</div><div class="stat-cell-sub up">+{{ integer(metrics.tickets_sold_this_week) }} this week</div><div v-if="metrics.capacity_ticket_units>0" class="stat-support stat-support--progress"><div class="stat-prog-copy"><span>{{ integer(metrics.tickets_sold) }} of {{ integer(metrics.capacity_ticket_units) }}</span><span>{{ progress }}% sold</span></div><div class="stat-prog-track"><div class="stat-prog-fill fill-pink" :style="{width:`${progress}%`}"></div></div></div></article><article class="stat-cell stat-cell--revenue"><div class="stat-cell-label">Revenue</div><div class="stat-cell-value">{{ money(metrics.gross_revenue_minor) }}</div><div class="stat-cell-sub up">+{{ money(metrics.gross_revenue_this_week_minor) }} this week</div></article><article class="stat-cell stat-cell--spots"><div class="stat-cell-label">Spots left</div><div class="stat-cell-value">{{ integer(metrics.spots_left) }}</div><div class="stat-cell-sub neutral">of {{ integer(metrics.capacity_admissions) }} attendee spots</div></article><article class="stat-cell stat-cell--views"><div class="stat-cell-label">Page views</div><div class="stat-cell-value">{{ integer(metrics.page_views) }}</div><div class="stat-cell-sub neutral"><template v-if="metrics.conversion_percent !== null">{{ metrics.conversion_percent }}% bought a ticket</template><template v-else>No conversion data yet</template></div></article></div></template>
